export const getProductsByCategory = (slug: CategorySlug): Product[] =>
  PRODUCTS.filter((p) => p.categories.includes(slug));

export const getCategory = (slug: string): Category | undefined =>
  CATEGORIES.find((c) => c.slug === slug);
